test("the Automation output branch stays clear of the direction and review words", async ({
  page,
}) => {
  for (const text of ["100%", "150%", "200%"]) {
    await open(page, "/", 1440);
    await page.evaluate((size) => {
      document.documentElement.style.fontSize = size;
    }, text);
    await page
      .getByRole("button", { name: "Automations", exact: true })
      .click();
    const field = page.locator(".services-art .system-field");
    await expect(
      field.getByText("Human direction", { exact: true }),
    ).toBeVisible();
    await expect(
      field.getByText("Human review", { exact: true }),
    ).toBeVisible();
    // Read the rendered path and text geometry, rather than pinning a path string.
    const collisions = await field.evaluate((element) => {
      const path = element.querySelector<SVGPathElement>(
        '[data-links~="human>out1"] path',
      )!;
      const transform = path.getScreenCTM()!;
      const labels = [
        ...element.querySelectorAll(
          '[data-node="human"] .system-label-text, [data-node="n3"] .system-label-text',
        ),
      ].map((label) => {
        const range = document.createRange();
        range.selectNodeContents(label);
        return { text: label.textContent, boxes: [...range.getClientRects()] };
      });
      const length = path.getTotalLength();
      const hits = new Set<string>();
      for (let distance = 0; distance <= length; distance += 0.5) {
        const point = path
          .getPointAtLength(distance)
          .matrixTransform(transform);
        for (const label of labels)
          if (
            label.boxes.some(
              (box) =>
                point.x >= box.left - 1 &&
                point.x <= box.right + 1 &&
                point.y >= box.top - 1 &&
                point.y <= box.bottom + 1,
            )
          )
            hits.add(label.text ?? "");
      }
      return [...hits];
    });
    expect(collisions, text).toEqual([]);
  }
});

test("the Workflows drawing reads as an ordered process with a labelled iteration", async ({
  page,
}) => {
  await open(page, "/", 1440);
  await page.getByRole("button", { name: "Workflows", exact: true }).click();
  const field = page.locator(".services-art .system-field");
  // The decision/review point and the iteration are named in visible words,
  // not left to arrow-decoding.
  await expect(
    field.getByText("Review point: does it still fit the work?", {
      exact: true,
    }),
  ).toBeVisible();
  await expect(
    field.getByText("Iteration back into tailored design and build", {
      exact: true,
    }),
  ).toBeVisible();
  // The accessible description carries the same order and iteration in words.
  await expect(field).toHaveAccessibleName(
    /brief.*tailored design and build.*test and review.*team deployment.*review in the customer context.*feeds back into tailored design and build/i,
  );
  // The landscape connectors read as the ordered chain 1→2→3→4→5: each step
  // leads to the next, and nothing gathers the first three into deployment.
  const chain = ["n1>n2", "n2>n3", "n3>human", "human>n4", "n4>n2"];
  await expect
    .poll(
      async () =>
        [
          ...new Set(
            (await field.evaluate(readField)).parts.flatMap(
              (piece) => piece.links,
            ),
          ),
        ].sort(),
      { timeout: 15_000 },
    )
    .toEqual([...chain].sort(), "landscape");
  // The portrait drawing returns to the design step, not the brief, and its
  // connectors read as the same ordered chain.
  await open(page, "/", 390);
  const portrait = page.locator(
    "#service-automation .service-figure .system-field",
  );
  await expect(
    portrait.getByText("Iteration back into tailored design and build", {
      exact: true,
    }),
  ).toBeVisible();
  await expect
    .poll(
      async () =>
        [
          ...new Set(
            (await portrait.evaluate(readField)).parts.flatMap(
              (piece) => piece.links,
            ),
          ),
        ].sort(),
      { timeout: 15_000 },
    )
    .toEqual([...chain].sort(), "portrait");
});

