test("the builder stations start at Design and keep their reviewed steps", async ({
  page,
}) => {
  await open(page, "/", 1440);
  const state = await page
    .locator("#audience-builders .scene-field")
    .evaluate(readField);
  expect(state.labels.map((label) => label.text)).toEqual([
    "A learner with a work problem",
    "Design",
    "Test",
    "Troubleshoot",
    "Anticipate failures",
    "Workflow in use",
  ]);
  // Design arrives before Test in the story, and each step carries a check.
  const beats = Object.fromEntries(
    state.labels.map((label) => [label.text, label.beat]),
  );
  expect(beats.Design).toBeLessThan(beats.Test);
  expect(
    drawnMarks(state).filter((mark) => mark.startsWith("check")),
  ).toHaveLength(4);
  expect(state.describedBy).toMatch(
    /works with colleagues through four reviewed stations.*design, test, troubleshoot, anticipate failures.*three joined parts/i,
  );
  expect(state.describedBy).not.toMatch(/climb|stair/i);
});

test("the executive day names four ordered cards and keeps the decision illustrative", async ({
  page,
}) => {
  const labels = [
    "Claude Daily Brief",
    "Meeting Brief",
    "Meeting Debrief",
    "Actions from Transcripts",
  ];
  // Each card carries a short fictional sample of what it produces: the two
  // briefs prepare, the debrief follows up, the last card acts on transcripts.
  const samples = [
    "Sample: 3 priorities",
    "Sample: agenda draft",
    "Sample: owners, dates",
    "Sample: tasks from notes",
  ];
  for (const route of ["/", "/services/"]) {
    for (const width of [1440, 384]) {
      await open(page, route, width);
      const panel = page.locator("#audience-executives");
      const field = panel.locator(".scene-field");
      const words = await field.locator(".system-label").allTextContents();
      expect(
        words
          .filter((word) => labels.includes(word.trim()))
          .map((word) => word.trim()),
      ).toEqual(labels);
      for (const sample of samples)
        await expect(field.getByText(sample, { exact: true })).toHaveCount(1);
      // The samples read as preparation, follow-up and transcript actions,
      // and every one is marked as a sample rather than real output.
      await expect(field.getByText(/3 priorities/)).toBeVisible();
      await expect(field.getByText(/agenda draft/)).toBeVisible();
      await expect(field.getByText(/owners, dates/)).toBeVisible();
      await expect(field.getByText(/tasks from notes/)).toBeVisible();
      await expect(field.getByText("You decide", { exact: true })).toHaveCount(
        1,
      );
      for (const removed of [
        "Your operating problem",
        "Tailored executive skill",
        "Executive direction",
      ])
        await expect(field.getByText(removed, { exact: true })).toHaveCount(0);
      await expect(field).toHaveAccessibleName(
        /Claude Daily Brief.*Meeting Brief.*Meeting Debrief.*Actions from Transcripts.*You decide.*illustrative.*no live calendar, email, CRM or transcript integration/i,
      );
      await expect(panel.locator(".audience-caption")).toContainText(
        "Claude Daily Brief → Meeting Brief → Meeting Debrief → Actions from Transcripts",
      );
      await expect(panel.locator(".audience-caption")).toContainText(
        "no live calendar, email, CRM or transcript integration",
      );
    }
  }
});

